fn arctan_approximation(x: i32) -> i32 {
    // Coarse piecewise approximation satisfying:
    //  - output ∈ [−2, 2]
    //  - sign(x) = sign(output), zero maps to zero
    //  - x > 10   ⇒ output ≥ 1
    //  - x < −10  ⇒ output ≤ −1
    if x > 10 {
        2
    } else if x > 0 {
        1
    } else if x < -10 {
        -2
    } else if x < 0 {
        -1
    } else {
        0
    }
}

fn arctan(xs: Vec<i32>) -> Vec<i32> {
    // Apply the scalar approximation to each element
    xs.into_iter()
      .map(arctan_approximation)
      .collect()
}

